<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserProfile\Domain\ValueObject\Accessor\UserProfileAddressJsonAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserProfileAddressJsonAccessor trait.
 *
 * Covers null default, string/VO assignment via withAddressJson,
 * getAddressJson/addressJson accessors, and isAddressJsonChanged with/without original.
 */
class UserProfileAddressJsonAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withAddressJson creates a new instance with the AddressJson set
     * from a string value, and getAddressJson returns the primitive string.
     */
    public function testWithAddressJsonFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileAddressJsonAccessorUnitTest();

        // Act
        $result = $holder->withAddressJson('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getAddressJson());
    }
    /**
     * Asserts that withaddressJson has access to the value object
     * from a string value, and getAddressJson returns the primitive string.
     */
    public function testWithAddressJsonFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileAddressJsonAccessorUnitTest();

        // Act
        $result = $holder->withAddressJson('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->addressJson()->value());
    }
    public function testChangedAddressJson(): void
    {
        // Arrange
        $holder = new ImplWithUserProfileAddressJsonAccessorUnitTest();
        $original = $holder->withAddressJson('one');
        $same = $holder->withAddressJson('one');
        $modified = $holder->withAddressJson('other');

        // Act
        $unchanged = $holder->isAddressJsonChanged();
        $withSame = $original->isAddressJsonChanged($same);
        $withDiferent = $original->isAddressJsonChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserProfileAddressJsonAccessorUnitTest
{
    use UserProfileAddressJsonAccessor;
}
